const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  depserverUrl: 'http://mdm-depserver.mdm.svc.cluster.local:9001',
  scepUrl: 'http://mdm-scep.mdm.svc.cluster.local:8080',
  publicHost: 'mdm-prod.pke-lab.de',
  depName: 'capulus',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM',
  vmUrl: 'http://vmsingle-monitoring-victoria-metrics-k8s-stack.monitoring.svc.cluster.local:8428',
  n8nUrl: 'https://n8n.prod.homeserver'
};
return [{ json: cfg }];

const input = $('Formular Sperren').first().json;
const message = String(input['Nachricht'] || '').trim();
const phone = String(input['Telefonnummer (optional)'] || '').trim();
const serial = String(input['Seriennummer (leer = alle iPads)'] || '').trim();
const fail = (text) => [{ json: { ok: false, title: 'Nichts gesperrt', message: text } }];
if (input['Bestaetigung'] !== 'Ja, jetzt sperren') return fail('Die Bestaetigung steht nicht auf \"Ja, jetzt sperren\". Es wurde kein Geraet gesperrt.');
if (message.length === 0 || message.length > 300) return fail('Die Nachricht muss 1 bis 300 Zeichen lang sein.');
if (phone.length > 40 || !/^[0-9+() \/.-]*$/.test(phone)) return fail('Die Telefonnummer darf nur Ziffern, Leerzeichen und + ( ) / . - enthalten.');
if (serial.length > 40 || !/^[A-Za-z0-9]*$/.test(serial)) return fail('Die Seriennummer darf nur Buchstaben und Ziffern enthalten.');
return [{ json: { ok: true, message, phone, serial } }];

const crypto = require('crypto');
const input = $('Eingabe pruefen').first().json;
const devices = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
if (devices.length === 0) return [{ json: { skip: true } }];
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
return devices.map((device) => {
  const commandUuid = crypto.randomUUID();
  let command = '\t\t<key>Message</key>\n\t\t<string>' + escapeXml(input.message) + '</string>\n';
  if (input.phone) command += '\t\t<key>PhoneNumber</key>\n\t\t<string>' + escapeXml(input.phone) + '</string>\n';
  const plist = '<?xml version="1.0" encoding="UTF-8"?>\n'
    + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
    + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n' + command
    + '\t\t<key>RequestType</key>\n\t\t<string>DeviceLock</string>\n\t</dict>\n\t<key>CommandUUID</key>\n\t<string>'
    + commandUuid + '</string>\n</dict>\n</plist>\n';
  return { json: { skip: false, enrollment_id: device.enrollment_id, serial_number: device.serial_number, command_uuid: commandUuid, plist } };
});

const sent = $('Befehle bauen').all().map((item) => item.json).filter((row) => !row.skip);
const results = $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  const pushError = Object.values(body.status || {}).map((entry) => entry.push_error).filter(Boolean).join('; ');
  return { serial: source.serial_number || source.enrollment_id, queued, pushError, detail: queued ? '' : String(response.json.statusCode || response.json.error || 'keine Antwort') };
});
const ok = results.filter((row) => row.queued);
const failed = results.filter((row) => !row.queued);
const pushErrors = ok.filter((row) => row.pushError);
const lines = [ok.length + ' von ' + results.length + ' iPad(s) erhalten den Sperrbefehl: ' + (ok.map((row) => row.serial).join(', ') || '-') + '.'];
if (failed.length > 0) lines.push('Nicht eingereiht: ' + failed.map((row) => row.serial + ' (' + row.detail + ')').join(', ') + '.');
if (pushErrors.length > 0) lines.push('Push fehlgeschlagen, diese iPads sperren sich erst beim naechsten Check-in: ' + pushErrors.map((row) => row.serial).join(', ') + '.');
return [{ json: { title: failed.length > 0 ? 'Sperren teilweise fehlgeschlagen' : 'Sperrbefehl gesendet', message: lines.join(' '), priority: failed.length > 0 ? 'high' : 'default' } }];
